-- 06_lviv_real_data.sql — реальні опубліковані дані для Львівської області.
-- Кожне значення має джерело (provenance + source_url). Нічого не домислено:
--   * AP (антропогенне навантаження) в джерелах відсутнє → NULL, його вводить експерт
--     через анкету в інтерфейсі (5 критеріїв × 0..2) перед запуском FIS;
--   * якщо в джерелі немає показника → NULL, оцінка FIS для запису не формується;
--   * координати районних середніх — умовний центр району (location_type='district_average'),
--     координати Гологорів — центр села (поле в джерелі не локалізоване).
BEGIN;

-- 1. Середні 2001–2020 рр. по природно-сільськогосподарських районах
--    Джерело: Камалова Є. Забруднення ґрунтів земель сільськогосподарського призначення
--    Львівської області важкими металами : курсова робота / наук. кер. Паньків З.П. —
--    ЛНУ ім. І. Франка, 2024. Табл. 4.2 (за даними Львівської філії ДУ «Держґрунтохорона»;
--    звіт Демчишин А.М., Турчак І.Я., Кушнір Н.І., Павленко Г.М., Львів, 2021).
--    Методи (табл. 3.1): рухомі Cd, Pb — ДСТУ 4770.3:2007, Zn — ДСТУ 4770.2:2007; ААБР pH 4,8; ААС.
--    pH: середньозважене pH(KCl) по ОБЛАСТІ = 6,0 у IX, X і XI турах (2006–2020):
--    Грищенко О.М., Демчишин А.М., Хмарська Ю.Ю. Динаміка показників родючості ґрунтів
--    Львівської області, 2023, табл. 1. Районних значень pH у відкритих джерелах не знайдено.
INSERT INTO monitoring_locations(id,name,latitude,longitude,land_use,source_status,description,district,location_type,area_thousand_ha,is_demo) VALUES
