-- Характеристики ділянок: лише задокументовані факти, решта NULL (= невідомо)
INSERT INTO site_characteristics(location_id, contamination_confirmed, notes)
SELECT id, NULL, 'Немає даних — заповнює фахівець' FROM monitoring_locations WHERE id IN (1,2,3,4,5,6,7,10)
ON CONFLICT(location_id) DO NOTHING;
INSERT INTO site_characteristics(location_id, contamination_confirmed, notes) VALUES
(8, FALSE, 'У джерелі: забруднення важкими металами «не спостерігалося»'),
(9, FALSE, 'У джерелі: забруднення важкими металами «не спостерігалося»')
ON CONFLICT(location_id) DO UPDATE SET contamination_confirmed=EXCLUDED.contamination_confirmed, notes=EXCLUDED.notes;

SELECT setval(pg_get_serial_sequence('monitoring_locations','id'), (SELECT MAX(id) FROM monitoring_locations));
SELECT setval(pg_get_serial_sequence('soil_measurements','id'), (SELECT MAX(id) FROM soil_measurements));
COMMIT;
